package python

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/r2cuerdame/codesamplex/internal/scanner"
)

func entriesByName(entries []lockEntry) map[string]lockEntry {
	out := make(map[string]lockEntry, len(entries))
	for _, e := range entries {
		out[e.Name] = e
	}
	return out
}

func TestScanPackagesReadsHashedRequirements(t *testing.T) {
	dir := t.TempDir()
	data := strings.Join([]string{
		"#",
		"# This file is autogenerated by pip-compile with Python 3.12",
		"#",
		"django==4.2.7 \\",
		"    --hash=sha256:aa \\",
		"    --hash=sha256:bb",
		"    # via -r requirements.in",
		"asgiref==3.7.2 \\",
		"    --hash=sha256:cc",
		"    # via django",
		"",
	}, "\r\n")
	if err := os.WriteFile(filepath.Join(dir, "requirements.txt"), []byte(data), 0o644); err != nil {
		t.Fatal(err)
	}
	pkgs, err := New().ScanPackages(context.Background(), dir)
	if err != nil {
		t.Fatal(err)
	}
	byName := map[string]scanner.ResolvedPackage{}
	for _, p := range pkgs {
		byName[p.PURL.Name] = p
	}
	for name, version := range map[string]string{"django": "4.2.7", "asgiref": "3.7.2"} {
		p, ok := byName[name]
		if !ok {
			t.Fatalf("%s missing from %+v", name, pkgs)
		}
		if p.PURL.Version != version || p.Source != "requirements.txt" || !p.Direct {
			t.Errorf("%s = %+v, want version %s from requirements.txt, direct", name, p, version)
		}
	}
	if len(pkgs) != 2 {
		t.Errorf("got %d packages, want 2: %+v", len(pkgs), pkgs)
	}
}

func TestParseRequirementsHashAndContinuation(t *testing.T) {
	data := strings.Join([]string{
		"requests==2.31.0 --hash=sha256:aa --hash=sha256:bb",
		"urllib3[socks] == 2.2.1 \\",
		"    --hash=sha256:cc",
		`typing-extensions==4.9.0 ; python_version >= "3.8" \`,
		"    --hash=sha256:dd \\",
		"    --hash=sha256:ee",
		"six==1.16.0 \\",
		"    # via python-dateutil",
		"    --hash=sha256:ff",
		"--hash=sha256:00",
		"    --hash sha256:11",
		"django==4.2.* \\",
		"    --hash=sha256:22",
		"split==1.\\",
		"0",
		"tail==2.0 \\",
	}, "\n")
	got := entriesByName(parseRequirements([]byte(data)))
	want := map[string]string{
		"requests":          "2.31.0",
		"urllib3":           "2.2.1",
		"typing-extensions": "4.9.0",
		"six":               "1.16.0",
		"split":             "1.0",
		"tail":              "2.0",
	}
	for name, version := range want {
		e, ok := got[name]
		if !ok {
			t.Errorf("%s not read: %+v", name, got)
			continue
		}
		if e.Version != version || e.Private {
			t.Errorf("%s = %+v, want public pin %s", name, e, version)
		}
	}
	if len(got) != len(want) {
		t.Errorf("got %+v, want only %v", got, want)
	}
}

func TestParseRequirementsPrivateRefsWithContinuation(t *testing.T) {
	data := strings.Join([]string{
		"-e ./libs/core \\",
		"    --hash=sha256:aa",
		"-e git+https://example.com/org/tool.git#egg=tool \\",
		"    --hash=sha256:bb",
		"./vendor/pkg \\",
		"    --hash=sha256:cc",
		"file:///opt/wheels/thing.whl \\",
		"    --hash=sha256:dd",
		"git+https://example.com/org/other.git \\",
		"    --hash=sha256:ee",
	}, "\n")
	entries := parseRequirements([]byte(data))
	got := entriesByName(entries)
	for _, name := range []string{"core", "tool", "pkg", "thing.whl", "other"} {
		e, ok := got[name]
		if !ok {
			t.Errorf("%s not recorded: %+v", name, entries)
			continue
		}
		if !e.Private || e.Version != "" {
			t.Errorf("%s = %+v, want PRIVATE without version", name, e)
		}
	}
	for _, e := range entries {
		if strings.HasPrefix(e.Name, "--") || strings.Contains(e.Name, `\`) || strings.Contains(e.Name, "sha256") {
			t.Errorf("private entry named from an option or continuation: %+v", e)
		}
	}
	if len(entries) != 5 {
		t.Errorf("got %d entries, want 5: %+v", len(entries), entries)
	}
}
